example.source:
ja certifier 0.3
module corpus.ja_certifier.example_02251
policy no_execute_unknown_code
policy no_network
grammar Grammar02251 {
  mode DEFAULT { token IDENT = letter, { letter | digit } ; }
  precedence left "+" "-" level 10 ;
  precedence left "*" "/" level 20 ;
  production expression @ast(BinaryExpr) = expression, operator, expression | IDENT ;
  recovery expression synchronize [";", "}"] ;
  diagnostic JCG-02251 when unexpected_token ;
}
validate parser Grammar02251 with lalr1
assert certificate.semantic_hash == "invalid-02251"

